-- Generated by pnpm db:generate and changed by hand: the UPDATE between the
-- column and its CHECK fills the jobs stored before it. A job carries the
-- portal principal of the account that queued it (lib/access.ts principal()).
-- The account whose auth_email is the stored actor_email gives its
-- auth_principal, so jobs that Entra ID accounts queued (entra:<tid>:<oid>)
-- get their real principal; any other actor_email gets the local key
-- 'private:' || actor_email that the claim guards rebuilt until now. Rows
-- without actor_email keep NULL.
ALTER TABLE "jobs" ADD COLUMN "actor_principal" text;--> statement-breakpoint
UPDATE "jobs" SET "actor_principal"=COALESCE((SELECT "local_users"."auth_principal" FROM "local_users" WHERE "local_users"."auth_email"="jobs"."actor_email"),'private:' || "jobs"."actor_email") WHERE "actor_email" IS NOT NULL;--> statement-breakpoint
ALTER TABLE "jobs" ADD CONSTRAINT "jobs_actor_principal" CHECK ((actor_principal IS NULL) = (actor_email IS NULL));
